import{_ as a,o as t,c as n,a3 as s}from"./chunks/framework.BlfGB29P.js";const d=JSON.parse('{"title":"系统架构设计","description":"从架构驱动因素出发，建立系统边界、控制结构、数据拓扑、租户隔离和外部集成。","frontmatter":{"title":"系统架构设计","description":"从架构驱动因素出发，建立系统边界、控制结构、数据拓扑、租户隔离和外部集成。"},"headers":[],"relativePath":"py-agent/architecture/system-architecture/index.md","filePath":"py-agent/architecture/system-architecture/index.md","lastUpdated":1786083160000}'),i={name:"py-agent/architecture/system-architecture/index.md"};function r(l,e,c,p,o,h){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="系统架构设计" tabindex="-1">系统架构设计 <a class="header-anchor" href="#系统架构设计" aria-label="Permalink to &quot;系统架构设计&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>本分组建立 Agent 系统的整体骨架。学习顺序从“系统必须解决什么问题”开始，再决定组件和控制权，最后处理数据、租户与外部系统边界。框架、数据库和云产品只有在这些问题明确后才进入候选。</p><h2 id="_1-学习目标" tabindex="-1">1. 学习目标 <a class="header-anchor" href="#_1-学习目标" aria-label="Permalink to &quot;1. 学习目标&quot;">​</a></h2><p>完成本分组后，你应该能够：</p><ol><li>把业务目标转成可验证的功能需求、约束和质量属性场景；</li><li>区分系统上下文、运行容器、内部组件和代码实现；</li><li>决定哪些步骤由函数、Workflow、单 Agent 或多 Agent 控制；</li><li>为权威数据、执行状态和派生数据选择存储拓扑；</li><li>让租户边界贯穿数据、Checkpoint、检索、缓存、工具和运营；</li><li>在同步、异步、Webhook、回调和文件接入之间选择外部集成模式；</li><li>用失败路径、恢复目标和验收证据审查整体架构。</li></ol><h2 id="_2-文章顺序" tabindex="-1">2. 文章顺序 <a class="header-anchor" href="#_2-文章顺序" aria-label="Permalink to &quot;2. 文章顺序&quot;">​</a></h2><ol><li><a href="/py-agent/architecture/system-architecture/requirements-constraints-quality-attributes">需求、约束与质量属性</a>：识别架构输入、硬约束和可测质量场景。</li><li><a href="/py-agent/architecture/system-architecture/system-boundaries-component-responsibilities">系统边界与组件职责</a>：确定系统内外、组件所有权和依赖方向。</li><li><a href="/py-agent/architecture/system-architecture/agent-workflow-multi-agent-architecture">Agent、Workflow 与多 Agent 架构</a>：分配代码与模型的控制权，选择最简单可行结构。</li><li><a href="/py-agent/architecture/system-architecture/data-state-storage-architecture">数据、状态与存储架构</a>：比较存储拓扑，定义权威源、一致性和恢复链。</li><li><a href="/py-agent/architecture/system-architecture/multi-tenancy-architecture">多租户架构</a>：选择隔离拓扑并验证租户边界贯穿全链路。</li><li><a href="/py-agent/architecture/system-architecture/external-integration-architecture">外部系统集成架构</a>：选择交互模式，处理外部身份、可靠性和不可信内容。</li></ol><p>前四篇建立一个系统内部的责任和数据骨架，后两篇处理系统跨租户和跨外部依赖时的边界。它们共同形成系统设计，不应被当成六份独立检查表。</p><h2 id="_3-知识链" tabindex="-1">3. 知识链 <a class="header-anchor" href="#_3-知识链" aria-label="Permalink to &quot;3. 知识链&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户任务与质量属性</span></span>
<span class="line"><span>  -&gt; 系统边界和组件责任</span></span>
<span class="line"><span>  -&gt; 控制权：函数 / Workflow / Agent / 多 Agent</span></span>
<span class="line"><span>  -&gt; 数据权威源、存储拓扑与恢复</span></span>
<span class="line"><span>  -&gt; 租户隔离和资源边界</span></span>
<span class="line"><span>  -&gt; 外部系统契约与故障处理</span></span>
<span class="line"><span>  -&gt; 架构决策、实验和验收证据</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>后面的选择必须能追溯到前面的驱动因素。例如“采用独立向量数据库”应对应规模或隔离实验，“拆成多 Agent”应对应上下文、权限或并行约束，而不能只因为技术看起来更完整。</p><h2 id="_4-贯穿场景" tabindex="-1">4. 贯穿场景 <a class="header-anchor" href="#_4-贯穿场景" aria-label="Permalink to &quot;4. 贯穿场景&quot;">​</a></h2><p>建议使用一个任务贯穿本组，例如“售后专员根据订单和政策生成退款建议，并在确认后创建退款”：</p><ul><li>用需求文章定义事实准确率、未确认不得退款和响应时间；</li><li>用边界文章分开业务规则、Agent Runtime、工具和数据；</li><li>用控制结构文章决定建议阶段开放、退款阶段固定；</li><li>用数据文章确定业务记录、Checkpoint、索引和缓存的权威关系；</li><li>用多租户文章验证不同商家订单和知识不会串读；</li><li>用外部集成文章处理订单查询、退款幂等和状态对账。</li></ul><p>同一场景可以让读者看到每篇文章解决的是不同架构问题，而不是反复描述同一套组件。</p><h2 id="_5-分组边界" tabindex="-1">5. 分组边界 <a class="header-anchor" href="#_5-分组边界" aria-label="Permalink to &quot;5. 分组边界&quot;">​</a></h2><p>本组不展开 FastAPI 路由、PostgreSQL 表、Redis 命令、LangGraph API 或具体部署 YAML。它负责架构决策和系统不变量；实现进入“Agent 应用工程”和“工作流与多 Agent”，验证机制进入“质量与生产”。</p><p>完成本组时，产物应是一组有驱动因素、有责任、有失败语义的设计，而不是一张只列模型、数据库和队列名称的组件图。</p>`,19)])])}const m=a(i,[["render",r]]);export{d as __pageData,m as default};
